package core;

public class BitwiseOperator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
int a=12;
int b=25;
System.out.println(a&b);
System.out.println(a | b);
System.out.println(a^b);
int m=34;
int n=68;
System.out.println(m&n);
System.out.println(m | n);
System.out.println(m^n);

	}

}
